import{_ as t,c as n,o as s,ag as i}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Structured Analytic Techniques (SATs)","description":"","frontmatter":{"title":"Structured Analytic Techniques (SATs)"},"headers":[],"relativePath":"general/structured-analytic-techniques-sats.md","filePath":"general/structured-analytic-techniques-sats.md","lastUpdated":null}'),r={name:"general/structured-analytic-techniques-sats.md"};function a(o,e,d,h,l,p){return s(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="structured-analytic-techniques-sats" tabindex="-1">Structured Analytic Techniques (SATs) <a class="header-anchor" href="#structured-analytic-techniques-sats" aria-label="Permalink to &quot;Structured Analytic Techniques (SATs)&quot;">​</a></h1><h2 id="research-resources" tabindex="-1">Research Resources <a class="header-anchor" href="#research-resources" aria-label="Permalink to &quot;Research Resources&quot;">​</a></h2><h3 id="eight-rules-for-successful-brainstorming" tabindex="-1">Eight Rules for Successful Brainstorming <a class="header-anchor" href="#eight-rules-for-successful-brainstorming" aria-label="Permalink to &quot;Eight Rules for Successful Brainstorming&quot;">​</a></h3><p>See reference materials for brainstorming guidelines.</p><hr><h2 id="technique-level-1" tabindex="-1">Technique Level 1 <a class="header-anchor" href="#technique-level-1" aria-label="Permalink to &quot;Technique Level 1&quot;">​</a></h2><h3 id="technique-1-chronologies-and-timelines" tabindex="-1">Technique 1: Chronologies and Timelines <a class="header-anchor" href="#technique-1-chronologies-and-timelines" aria-label="Permalink to &quot;Technique 1: Chronologies and Timelines&quot;">​</a></h3><p><em>(Pherson and Heuer, 2021, p. 211)</em></p><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Identify all key events and arrange them chronologically in a table with one column for the date and one column for the event. (Beebe and Pherson, 2015, p. 159)</p></li><li><p><strong>STEP 2</strong>: Select relevant information from the event narrative and organize it along the timeline. Can the data be categorized? (Beebe and Pherson, 2015, p. 160)</p></li><li><p><strong>STEP 3</strong>: Review the timeline by asking questions:</p><ul><li>Are assumptions about evidence considered?</li><li>Does the duration and sequence of events make sense?</li><li>Are there gaps in the data?</li></ul></li></ol><p><em>Source: (Beebe and Pherson, 2015, p. 160)</em></p><h3 id="technique-1-getting-started-checklist" tabindex="-1">Technique 1: Getting Started Checklist <a class="header-anchor" href="#technique-1-getting-started-checklist" aria-label="Permalink to &quot;Technique 1: Getting Started Checklist&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: What prompted the analysis? Is it a report, development, or customer request? (Beebe and Pherson, 2015, p. 110)</p></li><li><p><strong>STEP 2</strong>: What is the key question that needs to be answered? (Beebe and Pherson, 2015, p. 110)</p></li><li><p><strong>STEP 3</strong>: Why is the issue important, and how will analysis make a difference? (Beebe and Pherson, 2015, p. 110)</p></li><li><p><strong>STEP 4</strong>: Has the question been answered before? What has changed? (Beebe and Pherson, 2015, p. 110-111)</p></li><li><p><strong>STEP 5</strong>: Who are the primary customers? Are their needs clear? (Beebe and Pherson, 2015, p. 111)</p></li><li><p><strong>STEP 6</strong>: Are there other stakeholders with differing perspectives? (Beebe and Pherson, 2015, p. 111)</p></li></ol><h3 id="technique-1-starbursting" tabindex="-1">Technique 1: Starbursting <a class="header-anchor" href="#technique-1-starbursting" aria-label="Permalink to &quot;Technique 1: Starbursting&quot;">​</a></h3><p>Find the template from <a href="https://www.mindtools.com/ab1w9zu/starbursting" target="_blank" rel="noreferrer">MindTools</a> or download here.</p><p><em>(Pherson and Heuer, 2021, p. 167)</em></p><table tabindex="0"><thead><tr><th>Question Type</th><th>Focus</th></tr></thead><tbody><tr><td><strong>What?</strong></td><td>Define the problem/question</td></tr><tr><td><strong>Why?</strong></td><td>Understand motivations</td></tr><tr><td><strong>Who?</strong></td><td>Identify stakeholders</td></tr><tr><td><strong>How?</strong></td><td>Determine methods</td></tr><tr><td><strong>When?</strong></td><td>Establish timing</td></tr><tr><td><strong>Where?</strong></td><td>Identify locations</td></tr></tbody></table><h3 id="technique-1-force-field-analysis" tabindex="-1">Technique 1: Force Field Analysis <a class="header-anchor" href="#technique-1-force-field-analysis" aria-label="Permalink to &quot;Technique 1: Force Field Analysis&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Define the problem or goal clearly. (Beebe and Pherson, 2015, p. 133)</p></li><li><p><strong>STEP 2</strong>: Brainstorm the main factors influencing the issue. (Beebe and Pherson, 2015, p. 133)</p></li><li><p><strong>STEP 3</strong>: Create two lists—one for supporting arguments and one for opposing ones. (Beebe and Pherson, 2015, p. 133)</p></li><li><p><strong>STEP 4</strong>: Assign values to the arguments to determine their strength. Calculate the total score to determine the dominant side. (Beebe and Pherson, 2015, p. 133)</p></li></ol><p><em>(Beebe and Pherson, 2015, p. 133)</em></p><h3 id="technique-1-key-assumptions-check" tabindex="-1">Technique 1: Key Assumptions Check <a class="header-anchor" href="#technique-1-key-assumptions-check" aria-label="Permalink to &quot;Technique 1: Key Assumptions Check&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Gather a group, including outsiders, to brainstorm assumptions. (Beebe and Pherson, 2015, p. 185)</p></li><li><p><strong>STEP 2</strong>: List assumptions on a whiteboard and critique them. (Beebe and Pherson, 2015, p. 185)</p></li><li><p><strong>STEP 3</strong>: Categorize assumptions as supported, uncertain, or unsupported. (Beebe and Pherson, 2015, p. 186)</p></li><li><p><strong>STEP 4</strong>: Refine the list and update based on group feedback. (Beebe and Pherson, 2015, p. 186)</p></li></ol><p><em>(Beebe and Pherson, 2015, p. 186)</em></p><h3 id="technique-1-red-hat-analysis-and-structured-brainstorming" tabindex="-1">Technique 1: Red Hat Analysis and Structured Brainstorming <a class="header-anchor" href="#technique-1-red-hat-analysis-and-structured-brainstorming" aria-label="Permalink to &quot;Technique 1: Red Hat Analysis and Structured Brainstorming&quot;">​</a></h3><p><em>Avoid mirror imaging—assuming others think like you. Red Hat Analysis helps to view problems as others might, particularly adversaries.</em></p><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Gather analysts with knowledge of the target, environment, or decision-makers. (Beebe and Pherson, 2015, p. 323)</p></li><li><p><strong>STEP 2</strong>: Use sticky notes to brainstorm without discussion. Focus on what the adversary would consider when acting. (Beebe and Pherson, 2015, p. 323)</p></li><li><p><strong>STEP 3</strong>: Group and analyze ideas for common themes. (Beebe and Pherson, 2015, p. 323)</p></li></ol><h3 id="technique-1-structured-brainstorming" tabindex="-1">Technique 1: Structured Brainstorming <a class="header-anchor" href="#technique-1-structured-brainstorming" aria-label="Permalink to &quot;Technique 1: Structured Brainstorming&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Gather a team of analysts. Use sticky notes for brainstorming, focusing on possible causes or factors. (Beebe and Pherson, 2015, p. 250)</p></li><li><p><strong>STEP 2</strong>: Post sticky notes on a wall and rearrange them into groups based on similarities. (Beebe and Pherson, 2015, p. 251)</p></li><li><p><strong>STEP 3</strong>: Analyze themes and draw conclusions for further investigation. (Beebe and Pherson, 2015, p. 251)</p></li></ol><hr><h2 id="technique-level-2" tabindex="-1">Technique Level 2 <a class="header-anchor" href="#technique-level-2" aria-label="Permalink to &quot;Technique Level 2&quot;">​</a></h2><h3 id="technique-2-deception-detection" tabindex="-1">Technique 2: Deception Detection <a class="header-anchor" href="#technique-2-deception-detection" aria-label="Permalink to &quot;Technique 2: Deception Detection&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Use deception detection checklists to assess the situation. Consider the motives, past practices, and the source&#39;s credibility. (Beebe and Pherson, 2015, p. 161)</p></li><li><p><strong>STEP 2</strong>: Analyze deception potential using checklists such as MOM (Motive, Opportunity, Means) and POP (Past Opposition Practices). (Pherson and Heuer, 2021, p. 256)</p></li></ol><h3 id="ai-content-detection" tabindex="-1">AI Content Detection <a class="header-anchor" href="#ai-content-detection" aria-label="Permalink to &quot;AI Content Detection&quot;">​</a></h3><p><strong>How to detect synthetic content:</strong></p><ul><li>Pay attention to details like hands, faces, lighting, textures, and patterns.</li><li>Use tools like <a href="https://wasitai.com" target="_blank" rel="noreferrer">Was It AI</a> and <a href="https://www.scribbr.com/ai-detector/" target="_blank" rel="noreferrer">Scribbr AI Detector</a>.</li></ul><h3 id="technique-2-decision-matrix" tabindex="-1">Technique 2: Decision Matrix <a class="header-anchor" href="#technique-2-decision-matrix" aria-label="Permalink to &quot;Technique 2: Decision Matrix&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Identify the decision or question. (Beebe and Pherson, 2015, p. 454)</p></li><li><p><strong>STEP 2</strong>: List criteria and options. Consolidate items to remove overlap. (Beebe and Pherson, 2015, p. 454)</p></li><li><p><strong>STEP 3</strong>: Assign weights and score options. Calculate the total score and choose the best option. (Beebe and Pherson, 2015, p. 456)</p></li></ol><p><strong>Decision Matrix Template:</strong></p><table tabindex="0"><thead><tr><th>Criteria</th><th>Weight</th><th>Option 1</th><th>Option 2</th><th>Option 3</th></tr></thead><tbody><tr><td>Criterion 1</td><td></td><td></td><td></td><td></td></tr><tr><td>Criterion 2</td><td></td><td></td><td></td><td></td></tr><tr><td>Criterion 3</td><td></td><td></td><td></td><td></td></tr><tr><td>Criterion 4</td><td></td><td></td><td></td><td></td></tr><tr><td>Criterion 5</td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Total Weighted Score</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Best Option</strong></td><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="technique-2-devil-s-advocacy" tabindex="-1">Technique 2: Devil&#39;s Advocacy <a class="header-anchor" href="#technique-2-devil-s-advocacy" aria-label="Permalink to &quot;Technique 2: Devil&#39;s Advocacy&quot;">​</a></h3><p><em>Devil&#39;s Advocacy helps critique decisions or plans by exploring what could go wrong.</em></p><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Start with the project&#39;s goals, assumptions, and gaps. (Beebe and Pherson, 2015, p. 187)</p></li><li><p><strong>STEP 2</strong>: Build a logical case against the proposed decision by focusing on potential pitfalls. (Beebe and Pherson, 2015, p. 187)</p></li></ol><h3 id="technique-2-mind-maps" tabindex="-1">Technique 2: Mind Maps <a class="header-anchor" href="#technique-2-mind-maps" aria-label="Permalink to &quot;Technique 2: Mind Maps&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Write the focal question at the center of the page. (Beebe and Pherson, 2015, p. 233)</p></li><li><p><strong>STEP 2</strong>: Brainstorm possible explanations and group ideas into categories. (Beebe and Pherson, 2015, p. 233)</p></li><li><p><strong>STEP 3</strong>: Expand the mind map by drawing connections between ideas. (Beebe and Pherson, 2015, p. 234)</p></li></ol><h3 id="technique-2-morphological-analysis" tabindex="-1">Technique 2: Morphological Analysis <a class="header-anchor" href="#technique-2-morphological-analysis" aria-label="Permalink to &quot;Technique 2: Morphological Analysis&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Define the problem&#39;s dimensions (group, activity, method, impact). (Beebe and Pherson, 2015, p. 404)</p></li><li><p><strong>STEP 2</strong>: Combine dimensions to generate alternative scenarios and refine them. (Beebe and Pherson, 2015, p. 404)</p></li></ol><h3 id="technique-2-multiple-hypothesis-generation—simple-hypotheses" tabindex="-1">Technique 2: Multiple Hypothesis Generation—Simple Hypotheses <a class="header-anchor" href="#technique-2-multiple-hypothesis-generation—simple-hypotheses" aria-label="Permalink to &quot;Technique 2: Multiple Hypothesis Generation—Simple Hypotheses&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Brainstorm hypotheses. Write them down and consolidate similar ideas. (Beebe and Pherson, 2015, p. 207)</p></li><li><p><strong>STEP 2</strong>: Clarify each hypothesis using Who, What, When, Where, and Why. (Beebe and Pherson, 2015, p. 207)</p></li><li><p><strong>STEP 3</strong>: Select the most promising hypotheses for further analysis. (Beebe and Pherson, 2015, p. 207)</p></li></ol><p><strong>Multiple Hypothesis Generation Table:</strong></p><table tabindex="0"><thead><tr><th>Hypothesis</th><th>Who</th><th>What</th><th>When</th><th>Where</th><th>Why</th></tr></thead><tbody><tr><td>Hypothesis 1</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Hypothesis 2</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Hypothesis 3</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Hypothesis 4</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Hypothesis 5</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Selected Promising Hypotheses for Further Analysis:</strong></p><ul><li>Selected Hypothesis 1: (e.g., Hypothesis 1 based on evidence and plausibility)</li><li>Selected Hypothesis 2: (e.g., Hypothesis 3 with strong indicators)</li></ul><h3 id="technique-2-pros-cons-faults-and-fixes" tabindex="-1">Technique 2: Pros-Cons-Faults-and-Fixes <a class="header-anchor" href="#technique-2-pros-cons-faults-and-fixes" aria-label="Permalink to &quot;Technique 2: Pros-Cons-Faults-and-Fixes&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Define the decision clearly. (Beebe and Pherson, 2015, p. 277)</p></li><li><p><strong>STEP 2</strong>: List pros and cons, and develop fixes for the cons. (Beebe and Pherson, 2015, p. 277)</p></li><li><p><strong>STEP 3</strong>: Compare the pros and cons, and assess the risk associated with each. (Beebe and Pherson, 2015, p. 278)</p></li></ol><h3 id="technique-2-what-if-analysis" tabindex="-1">Technique 2: What If? Analysis <a class="header-anchor" href="#technique-2-what-if-analysis" aria-label="Permalink to &quot;Technique 2: What If? Analysis&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Assume the event has occurred and develop a chain of reasoning for how it happened. (Beebe and Pherson, 2015, p. 350)</p></li><li><p><strong>STEP 2</strong>: Rank scenarios based on severity and probability. (Beebe and Pherson, 2015, p. 351)</p></li></ol><hr><h2 id="technique-level-3" tabindex="-1">Technique Level 3 <a class="header-anchor" href="#technique-level-3" aria-label="Permalink to &quot;Technique Level 3&quot;">​</a></h2><h3 id="technique-3-analysis-of-competing-hypotheses-ach" tabindex="-1">Technique 3: Analysis of Competing Hypotheses (ACH) <a class="header-anchor" href="#technique-3-analysis-of-competing-hypotheses-ach" aria-label="Permalink to &quot;Technique 3: Analysis of Competing Hypotheses (ACH)&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: List hypotheses to be considered. (Beebe and Pherson, 2015, p. 209)</p></li><li><p><strong>STEP 2</strong>: Assess information for consistency with each hypothesis. (Beebe and Pherson, 2015, p. 209)</p></li><li><p><strong>STEP 3</strong>: Refine hypotheses and conclusions based on inconsistencies. (Beebe and Pherson, 2015, p. 210)</p></li></ol><p><strong>ACH Matrix Template:</strong></p><table tabindex="0"><thead><tr><th>Evidence/Arguments</th><th>H1</th><th>H2</th><th>H3</th><th>H4</th><th>H5</th></tr></thead><tbody><tr><td>Evidence/Argument 1</td><td>C</td><td>I</td><td>N</td><td>C</td><td>I</td></tr><tr><td>Evidence/Argument 2</td><td>N</td><td>C</td><td>I</td><td>I</td><td>C</td></tr><tr><td>Evidence/Argument 3</td><td>I</td><td>N</td><td>C</td><td>C</td><td>I</td></tr><tr><td>Evidence/Argument 4</td><td>C</td><td>C</td><td>N</td><td>I</td><td>N</td></tr><tr><td>Evidence/Argument 5</td><td>I</td><td>N</td><td>C</td><td>I</td><td>C</td></tr><tr><td><strong>Total Inconsistencies</strong></td><td>X</td><td>Y</td><td>Z</td><td>A</td><td>B</td></tr></tbody></table><p><em>Key: C = Consistent, I = Inconsistent, N = Neutral</em></p><p><strong>Tentative Conclusion:</strong> The hypothesis with the fewest inconsistencies is the most likely.</p><p><em>(Pherson and Heuer, 2021, p. 245)</em></p><h3 id="technique-3-strengths-weaknesses-opportunities-threats-swot" tabindex="-1">Technique 3: Strengths-Weaknesses-Opportunities-Threats (SWOT) <a class="header-anchor" href="#technique-3-strengths-weaknesses-opportunities-threats-swot" aria-label="Permalink to &quot;Technique 3: Strengths-Weaknesses-Opportunities-Threats (SWOT)&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Define the objective clearly. (Beebe and Pherson, 2015, p. 188)</p></li><li><p><strong>STEP 2</strong>: List strengths, weaknesses, opportunities, and threats. (Beebe and Pherson, 2015, p. 188)</p></li><li><p><strong>STEP 3</strong>: Identify strategies for exploiting strengths and opportunities, and mitigating weaknesses and threats.</p></li></ol><p><em>(Beebe and Pherson, 2015, p. 188)</em></p><p><strong>SWOT Analysis Template:</strong></p><table tabindex="0"><thead><tr><th>Strengths</th><th>Weaknesses</th></tr></thead><tbody><tr><td>- Strength 1</td><td>- Weakness 1</td></tr><tr><td>- Strength 2</td><td>- Weakness 2</td></tr><tr><td>- Strength 3</td><td>- Weakness 3</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Opportunities</th><th>Threats</th></tr></thead><tbody><tr><td>- Opportunity 1</td><td>- Threat 1</td></tr><tr><td>- Opportunity 2</td><td>- Threat 2</td></tr><tr><td>- Opportunity 3</td><td>- Threat 3</td></tr></tbody></table><p><strong>Strategies for Action:</strong></p><p><em>Exploiting Strengths &amp; Opportunities:</em></p><ul><li>Strategy 1: (e.g., Use Strength 1 to maximize Opportunity 1)</li><li>Strategy 2: (e.g., Leverage Strength 2 to counter Threat 2)</li><li>Strategy 3: (e.g., Use Opportunity 3 to reduce Weakness 3)</li></ul><p><em>Mitigating Weaknesses &amp; Threats:</em></p><ul><li>Strategy 4: (e.g., Address Weakness 2 to avoid Threat 1)</li><li>Strategy 5: (e.g., Minimize Weakness 1 through Opportunity 2)</li></ul><h3 id="technique-3-foresight-quadrant-crunching" tabindex="-1">Technique 3: Foresight Quadrant Crunching <a class="header-anchor" href="#technique-3-foresight-quadrant-crunching" aria-label="Permalink to &quot;Technique 3: Foresight Quadrant Crunching&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Break the lead hypothesis into component parts and identify critical dimensions. (Beebe and Pherson, 2015, p. 354)</p></li><li><p><strong>STEP 2</strong>: Use 2x2 matrices to generate alternative scenarios. (Beebe and Pherson, 2015, p. 354)</p></li></ol><p><em>(Beebe and Pherson, 2015, p. 354)</em></p><h3 id="technique-3-indicators" tabindex="-1">Technique 3: Indicators <a class="header-anchor" href="#technique-3-indicators" aria-label="Permalink to &quot;Technique 3: Indicators&quot;">​</a></h3><p><strong>Step-by-Step Guide:</strong></p><ol><li><p><strong>STEP 1</strong>: Brainstorm indicators for each scenario. (Beebe and Pherson, 2015, p. 328)</p></li><li><p><strong>STEP 2</strong>: Refine the indicators, ensuring they are observable, valid, reliable, and stable. (Beebe and Pherson, 2015, p. 328)</p></li></ol><hr><h2 id="technique-level-4" tabindex="-1">Technique Level 4 <a class="header-anchor" href="#technique-level-4" aria-label="Permalink to &quot;Technique Level 4&quot;">​</a></h2><p><em>(To be expanded)</em></p><hr><h2 id="technique-level-5" tabindex="-1">Technique Level 5 <a class="header-anchor" href="#technique-level-5" aria-label="Permalink to &quot;Technique Level 5&quot;">​</a></h2><p><em>(To be expanded)</em></p><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Beebe, S. M., &amp; Pherson, R. H. (2015). <em>Cases in Intelligence Analysis: Structured Analytic Techniques in Action</em>.</li><li>Pherson, R. H., &amp; Heuer, R. J. (2021). <em>Structured Analytic Techniques for Intelligence Analysis</em>.</li></ul>',107)])])}const g=t(r,[["render",a]]);export{u as __pageData,g as default};
